  },
  "scan_execution_order": [
    {
      "stage": 1,
      "name": "edge sampling",
      "actions": [
        "Sample Enable and Tick once at the start of the scan.",
        "Do not re-read Enable or Tick later in the scan.",
        "Tick is treated as a logical invocation count: each scan with sampled Tick = TRUE counts as one tick when Enable = TRUE.",
        "No separate physical edge detection or wall-clock timing is required."
      ]
    },
    {
      "stage": 2,
      "name": "safety/reset priority and state transitions",
      "actions": [
        "First apply highest-priority safety reset: if !Enable, force state RED, phase := 0, age := 0, and skip Tick processing.",
        "Else execute exactly one transition using the sampled Tick and current retained state.",
        "If Enable & !Tick, hold phase and age.",
        "If Enable & Tick, compute age + 1; if the new age reaches the active threshold, advance phase := (phase + 1) mod 3 and set age := 0; otherwise retain phase and assign age := age + 1.",
        "Updated state becomes the retained state for the next scan q[k+1]."
      ]
    },
    {
      "stage": 3,
      "name": "unconditional top-level timer FB calls outside CASE/IF",
      "actions": [
        "No IEC TON/TOF/TP timer FBs are required because all durations are logical tick counts.",
        "If timer FBs are present for other purposes, call them unconditionally at top level outside CASE/IF; never place FB calls inside conditional state branches.",
        "For this design, stage 3 contains no conditional timer FB calls."
      ]
    },
    {
      "stage": 4,
      "name": "unified output assignments",
      "actions": [
        "Assign outputs exactly once after all transition processing.",
        "Phase := phase;",
        "Red := (phase = 0);",
        "Green := (phase = 1);",
        "Amber := (phase = 2);"
      ]
    }
  ],
  "formal_assertions": [
    {
      "id": "A1",
      "formula": "G((Red & !Green & !Amber) | (!Red & Green & !Amber) | (!Red & !Green & Amber))"
    },
    {
      "id": "A2",
      "formula": "G((Red <-> (Phase = 0)) & (Green <-> (Phase = 1)) & (Amber <-> (Phase = 2)) & (Phase >= 0) & (Phase <= 2))"
    },
    {
      "id": "A3",
      "formula": "G(!Enable -> (Red & !Green & !Amber & (Phase = 0)))"
    },
    {
      "id": "A4",
      "formula": "G((Red | Green | Amber))"
    }
  ]
}

